package com.payflow.notification; import org.springframework.kafka.annotation.KafkaListener; import org.springframework.stereotype.Component; import java.util.Map; @Component public class EventListener { @KafkaListener(topics="payment-events",groupId="notification-service") public void consume(Map<String,Object> e){System.out.println("[NOTIFICATION] Payment "+e.get("transactionId")+" is "+e.get("status"));} }
